/** The industry accordion: desktop columns and mobile tabs. Each state is a full render of the block. */
export default function Accordion({ kind }) {
  const states = kind === "desk" ? DESK : MOB;
  const [i, setI] = useState(kind === "desk" ? 0 : 0);
  return states[i]((k) => k >= 0 && k < states.length && setI(k));
}
